<script setup>
import { computed, ref, watch } from 'vue'
import { buildDeviceDirectory, deviceDirectorySelection } from '../utils/deviceDirectory.js'

const props = defineProps({ devices: { type: Array, default: () => [] }, workshops: { type: Array, default: () => [] }, lines: { type: Array, default: () => [] }, factoryId: String })
const selectedKey = ref(''), expanded = ref(new Set()), tableScroll = ref(null)
const directory = computed(() => buildDeviceDirectory(props))
const selected = computed(() => deviceDirectorySelection(directory.value, selectedKey.value))
function reveal(node) {
  const next = new Set(expanded.value)
  for (let parent = node; parent; parent = directory.value.nodeByKey.get(parent.parentKey)) if (parent.children?.length) next.add(parent.key)
  expanded.value = next
}
function choose(node) {
  if (!directory.value.nodeByKey.has(node.key)) return
  selectedKey.value = node.key; reveal(node)
  if (tableScroll.value) tableScroll.value.scrollTop = 0
}
function toggle(node) {
  const next = new Set(expanded.value); next.has(node.key) ? next.delete(node.key) : next.add(node.key); expanded.value = next
}
watch(directory, () => { const next = selected.value; if (selectedKey.value !== next.key) { selectedKey.value = next.key; reveal(next) } }, { immediate: true })
watch(() => props.factoryId, () => { selectedKey.value = directory.value.defaultKey; expanded.value = new Set(); reveal(selected.value) })
</script>

<template>
  <section class="device-management-browser" aria-label="设备管理">
    <header class="device-directory-heading"><div><h2>设备管理</h2><p>按车间、产线和设备类型查看，管理设备模型与数据连接。</p></div><slot name="actions" /></header>
    <div class="device-directory-workspace">
      <nav class="device-directory-nav" aria-label="设备分类导航">
        <header><strong>现场设备</strong><span>{{ directory.root.count }} 台</span></header>
        <div class="device-directory-tree">
          <button type="button" class="directory-node directory-root" :class="{ selected: selected.key === 'all' }" :aria-current="selected.key === 'all' ? 'true' : undefined" @click="choose(directory.root)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/></svg><span>全部设备</span><b>{{ directory.root.count }}</b></button>
          <ul>
            <li v-for="workshop in directory.root.children" :key="workshop.key">
              <div class="directory-branch">
                <button type="button" class="directory-expand" :aria-expanded="expanded.has(workshop.key)" :aria-label="(expanded.has(workshop.key) ? '收起' : '展开') + workshop.label" @click="toggle(workshop)"><svg :class="{ expanded: expanded.has(workshop.key) }" viewBox="0 0 16 16" aria-hidden="true"><path d="m6 3 5 5-5 5"/></svg></button>
                <button type="button" class="directory-node" :class="{ selected: selected.key === workshop.key }" :aria-current="selected.key === workshop.key ? 'true' : undefined" :title="workshop.label" @click="choose(workshop)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 21V8l6 4V8l6 4V3h6v18ZM7 16h1m4 0h1m4 0h1"/></svg><span>{{ workshop.label }}</span><b>{{ workshop.count }}</b></button>
              </div>
              <ul v-if="expanded.has(workshop.key)" class="directory-lines">
                <li v-for="line in workshop.children" :key="line.key">
                  <div class="directory-branch">
                    <button type="button" class="directory-expand" :aria-expanded="expanded.has(line.key)" :aria-label="(expanded.has(line.key) ? '收起' : '展开') + line.label" @click="toggle(line)"><svg :class="{ expanded: expanded.has(line.key) }" viewBox="0 0 16 16" aria-hidden="true"><path d="m6 3 5 5-5 5"/></svg></button>
                    <button type="button" class="directory-node" :class="{ selected: selected.key === line.key }" :aria-current="selected.key === line.key ? 'true' : undefined" :title="line.path.join(' / ')" @click="choose(line)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 12h18M6 8v8m6-8v8m6-8v8"/></svg><span>{{ line.label }}</span><b>{{ line.count }}</b></button>
                  </div>
                  <ul v-if="expanded.has(line.key)" class="directory-categories">
                    <li v-for="category in line.children" :key="category.key"><button type="button" class="directory-node directory-category" :class="{ selected: selected.key === category.key }" :aria-current="selected.key === category.key ? 'true' : undefined" :title="category.path.join(' / ')" @click="choose(category)"><span class="directory-type-dot" :class="category.type" aria-hidden="true"></span><span>{{ category.label }}</span><b>{{ category.count }}</b></button></li>
                  </ul>
                </li>
                <li v-if="!workshop.children.length" class="directory-no-lines">暂无产线</li>
              </ul>
            </li>
          </ul>
          <p v-if="!directory.root.children.length" class="directory-no-lines">还没有车间或设备</p>
        </div>
      </nav>
      <section class="device-directory-list" :aria-label="selected.path.join(' / ') + '设备列表'">
        <header class="device-list-heading"><div><div class="device-list-path" :title="selected.path.join(' / ')"><template v-for="(part, index) in selected.path.slice(0, -1)" :key="index"><span>{{ part }}</span><i aria-hidden="true">/</i></template></div><h3>{{ selected.label }}<span>{{ selected.count }} 台</span></h3></div><div class="device-type-summary"><span>固定 <b>{{ selected.fixedCount }}</b></span><span>辅助 <b>{{ selected.auxiliaryCount }}</b></span></div></header>
        <div ref="tableScroll" class="device-directory-table-scroll" tabindex="0" aria-label="滚动查看设备列表">
          <table class="device-directory-table"><colgroup><col class="directory-device-column"/><col class="directory-model-column"/><col class="directory-plc-column"/><col class="directory-action-column"/></colgroup><thead><tr><th>设备名称</th><th>使用模型</th><th>数据连接</th><th>操作</th></tr></thead>
            <tbody><tr v-for="row in selected.rows" :key="row.device.id" :data-device-id="row.device.id"><td><strong class="directory-device-name" :title="row.path">{{ row.device.name || row.device.id }}</strong><div class="directory-device-meta"><span class="directory-device-kind" :class="row.type">{{ row.type === 'auxiliary' ? '辅助' : '固定' }}</span><code :title="String(row.device.id)">{{ row.device.id }}</code></div></td><td class="directory-model-cell"><slot name="model" :device="row.device" /></td><td class="directory-connection-cell"><slot name="connection" :device="row.device" /></td><td class="directory-actions-cell"><div><slot name="row-actions" :device="row.device" /></div></td></tr>
              <tr v-if="!selected.count"><td colspan="4" class="device-directory-empty"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M9 38V17l10 6v-6l10 6V9h10v29ZM16 30h2m8 0h2"/></svg><strong>此分类暂无设备</strong><span>可使用右上角「添加设备」，或选择其他车间、产线。</span></td></tr>
            </tbody>
          </table>
        </div>
        <footer class="device-directory-footer">{{ selected.count }} 台设备<span>名称悬停查看完整现场路径</span></footer>
      </section>
    </div>
  </section>
</template>

<style scoped>
